def is_valid_parens(s):
    """
    Returns True if the string s is well-balanced with respect to brackets (), [], {}.
    Returns False otherwise.
    """
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}
    opening = set(['(', '[', '{'])

    for char in s:
        if char in opening:
            stack.append(char)
        elif char in bracket_map:
            if not stack or stack[-1] != bracket_map[char]:
                return False
            stack.pop()
        # Ignore any other characters

    return len(stack) == 0
```

